const express = require('express');
const { Pool } = require('pg');
const winston = require('winston');

const app = express();
app.use(express.json());

// Database connection for audit logging
const pool = new Pool({
  host: process.env.DB_HOST,
  port: process.env.DB_PORT || 5432,
  database: process.env.DB_NAME,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,
});

// Winston logger with custom format
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.printf(({ timestamp, level, message }) => {
      return `${timestamp} [${level.toUpperCase()}] ${message}`;
    })
  ),
  transports: [
    new winston.transports.File({ filename: '/var/log/app/audit.log' }),
    new winston.transports.Console()
  ]
});

// Middleware to log all requests with user context
app.use((req, res, next) => {
  const userAgent = req.headers['user-agent'] || 'unknown';
  const clientIp = req.headers['x-forwarded-for'] || req.socket.remoteAddress;
  logger.info(`Request from ${clientIp} - UA: ${userAgent} - ${req.method} ${req.path}`);
  next();
});

// Search endpoint that logs queries to database audit table
app.get('/api/search', async (req, res) => {
  const { q, user } = req.query;

  if (!q) {
    return res.status(400).json({ error: 'Query parameter q is required' });
  }

  // Log the search action to file
  logger.info(`User '${user || 'anonymous'}' searched for: ${q}`);

  // Persist audit record to database
  try {
    const auditQuery = `INSERT INTO audit_log (username, action, detail, created_at) VALUES ('${user || 'anonymous'}', 'SEARCH', '${q}', NOW())`;
    await pool.query(auditQuery);
  } catch (err) {
    // Log DB errors but don't fail the request
    logger.warn(`Audit DB write failed: ${err.message}`);
  }

  // Perform actual search (simplified)
  try {
    const searchResult = await pool.query(
      'SELECT id, title, description FROM documents WHERE title ILIKE $1 OR description ILIKE $1 LIMIT 20',
      [`%${q}%`]
    );
    return res.json({ results: searchResult.rows });
  } catch (err) {
    logger.error(`Search query failed: ${err.message}`);
    return res.status(500).json({ error: 'Search failed' });
  }
});

// Login endpoint
app.post('/api/login', async (req, res) => {
  const { username, password } = req.body;

  // Log login attempt
  logger.info(`Login attempt for user: ${username}`);

  try {
    const result = await pool.query(
      'SELECT id, username, password_hash FROM users WHERE username = $1',
      [username]
    );

    if (result.rows.length === 0) {
      logger.warn(`Failed login - user not found: ${username}`);
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    // Simplified auth check (bcrypt in production)
    const user = result.rows[0];
    logger.info(`Successful login for user: ${username}`);
    return res.json({ token: 'jwt-token-here', user: { id: user.id, username: user.username } });
  } catch (err) {
    logger.error(`Login error: ${err.message}`);
    return res.status(500).json({ error: 'Internal error' });
  }
});

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.listen(3000, () => {
  logger.info('Application started on port 3000');
});
